from economics_author import *

def drparts(defs, p0,p1,q0,q1, analyses, judgement, model):
    pc=Fraction(p1-p0,p0)*100;qc=Fraction(q1-q0,q0)*100;ped=qc/pc
    ps=[point('a',f'(i) Define {defs[0][0]}. [2]\n\n(ii) Define {defs[1][0]}. [2]',4,*[('A1',s) for term,ss in defs for s in ss]),
        point('b','Using the separate controlled demand study: (i) calculate the percentage change in price using the initial price as base [2]; (ii) calculate PED using initial-value percentage changes, showing working [3].',5,
            ('M1',f'(i) ({p1} − {p0})/{p0} × 100.'),('A1',f'{fmt(pc)}%.'),('M1',f'(ii) Quantity change = ({q1} − {q0})/{q0} ×100 = {fmt(qc)}%.'),('M1',f'PED = {fmt(qc)}/{fmt(pc)}.'),('A1',f'PED = {fmt(ped)} (absolute magnitude {fmt(abs(ped))}); no units. Accept exact fraction {ped}.'))]
    for label,(prompt,steps) in zip('cdef',analyses):
        ps.append(point(label,prompt,4,*[('A1' if j<2 else 'R1',s) for j,s in enumerate(steps)]))
    ps.append(bandpart('g',judgement,15,'data','Use this case\'s evidence to compare economic effects and reach a conditional judgement.',model))
    return ps,[{'expression':f'({p1}-{p0})/{p0}*100','expected':float(pc)},{'expression':f'(({q1}-{q0})/{q0})/(({p1}-{p0})/{p0})','expected':float(ped)}]

def essay(topic,family,v,code,title,level,scenario,a,b,am,bm,diagram):
    ps=[bandpart('a',a,10,'explain',a,am),bandpart('b','Using real-world examples you have studied, '+b,15,'essay',b,bm+' The supplied fictional case is an illustration, not a real-world example. To reach the top band, integrate a relevant actual example studied by the candidate, explaining its policy, mechanism and outcomes rather than naming it. Accept any accurate and developed example; no particular country, date or statistic is mandatory.')]
    add(topic,family,v,code,title, title.split(' — ')[0],level,'paper-1','essay','The following illustration is fictional and is not empirical evidence. '+scenario+' This is a complete 25-mark Paper 1 style question. In part (b), use actual examples you have studied.',ps,diagram,difficulty='hard')

